output=ROOT/'docs/mockups/erp';output.mkdir(parents=True,exist_ok=True);script=output/'browser-qa.cjs';script.write_text(js)
with ssh.connection(ssh.target(ssh.load_config(),'vps')) as client:
 stdin,stdout,stderr=client.exec_command('/usr/bin/python3 -u -c '+shlex.quote(remote),timeout=20)
 assert stdout.readline().strip()=='ready'
 tunnel=subprocess.Popen(['ssh','-o','BatchMode=yes','-o','ExitOnForwardFailure=yes','-L','127.0.0.1:18480:127.0.0.1:18400','-N','vps'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
 try:
  time.sleep(.8);result=subprocess.run(['node',str(script),str(output)],capture_output=True,text=True,timeout=60);assert result.returncode==0,result.stderr;(ROOT/'docs/ERP-BROWSER-RESULT.json').write_text(result.stdout);print(result.stdout)
 finally:
  tunnel.terminate();tunnel.wait(timeout=4);stdin.channel.shutdown_write();assert stdout.channel.recv_exit_status()==0
